window.SFT = {"duration":257.45,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if sound travelled faster than light?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.38},{"text":"sound","start":0.71},{"text":"travelled","start":1.04},{"text":"faster","start":1.37},{"text":"than","start":1.7},{"text":"light?","start":2.03}]}]},{"id":"start","n":2,"section":1,"title":false,"first":4.25,"end":21,"caps":[{"text":"8:52 PM, a corn farm in Iowa, under a tornado warning. Your daughter just ran into the corn after the dog.","show":4.25,"hide":9.65,"words":[{"text":"8:52","start":4.25},{"text":"PM,","start":4.43},{"text":"a","start":4.61},{"text":"corn","start":4.79},{"text":"farm","start":4.97},{"text":"in","start":5.15},{"text":"Iowa,","start":5.33},{"text":"under","start":5.51},{"text":"a","start":5.69},{"text":"tornado","start":5.87},{"text":"warning.","start":6.05},{"text":"Your","start":6.23},{"text":"daughter","start":6.41},{"text":"just","start":6.59},{"text":"ran","start":6.77},{"text":"into","start":6.95},{"text":"the","start":7.13},{"text":"corn","start":7.31},{"text":"after","start":7.49},{"text":"the","start":7.67},{"text":"dog.","start":7.85}]},{"text":"And sound just started travelling at 1 million km a second.","show":10.65,"hide":14.6,"words":[{"text":"And","start":10.65},{"text":"sound","start":10.901},{"text":"just","start":11.153},{"text":"started","start":11.404},{"text":"travelling","start":11.655},{"text":"at","start":11.907},{"text":"1","start":12.158},{"text":"million","start":12.41},{"text":"km","start":12.661},{"text":"a","start":12.912},{"text":"second.","start":13.164}]},{"text":"9 thunderclaps, still crawling across the fields towards you, hit you in the same instant.","show":15.6,"hide":21,"words":[{"text":"9","start":15.6},{"text":"thunderclaps,","start":15.852},{"text":"still","start":16.104},{"text":"crawling","start":16.356},{"text":"across","start":16.608},{"text":"the","start":16.86},{"text":"fields","start":17.112},{"text":"towards","start":17.364},{"text":"you,","start":17.616},{"text":"hit","start":17.868},{"text":"you","start":18.12},{"text":"in","start":18.372},{"text":"the","start":18.624},{"text":"same","start":18.876},{"text":"instant.","start":19.128}]}]},{"id":"flash","n":3,"section":1,"title":false,"first":22.4,"end":31.45,"caps":[{"text":"Thunder used to crawl behind the lightning at 343 m/s: 3 seconds for every kilometre.","show":22.4,"hide":27.65,"words":[{"text":"Thunder","start":22.4},{"text":"used","start":22.645},{"text":"to","start":22.89},{"text":"crawl","start":23.135},{"text":"behind","start":23.38},{"text":"the","start":23.625},{"text":"lightning","start":23.87},{"text":"at","start":24.115},{"text":"343","start":24.36},{"text":"m/s:","start":24.605},{"text":"3","start":24.85},{"text":"seconds","start":25.095},{"text":"for","start":25.34},{"text":"every","start":25.585},{"text":"kilometre.","start":25.83}]},{"text":"Now it comes with the flash.","show":29.05,"hide":31.45,"words":[{"text":"Now","start":29.05},{"text":"it","start":29.33},{"text":"comes","start":29.61},{"text":"with","start":29.89},{"text":"the","start":30.17},{"text":"flash.","start":30.45}]}]},{"id":"rule","n":4,"section":1,"title":false,"first":32.45,"end":37.85,"caps":[{"text":"In real physics this can't happen. Air would have to be 7 million times stiffer than steel.","show":32.45,"hide":37.85,"words":[{"text":"In","start":32.45},{"text":"real","start":32.672},{"text":"physics","start":32.895},{"text":"this","start":33.117},{"text":"can't","start":33.339},{"text":"happen.","start":33.562},{"text":"Air","start":33.784},{"text":"would","start":34.006},{"text":"have","start":34.229},{"text":"to","start":34.451},{"text":"be","start":34.674},{"text":"7","start":34.896},{"text":"million","start":35.118},{"text":"times","start":35.341},{"text":"stiffer","start":35.563},{"text":"than","start":35.785},{"text":"steel.","start":36.008}]}]},{"id":"rumble","n":5,"section":1,"title":false,"first":40.65,"end":50.05,"caps":[{"text":"That one was 6 km long. Its thunder used to roll on for 13 seconds, its far end heard last.","show":40.65,"hide":46.05,"words":[{"text":"That","start":40.65},{"text":"one","start":40.839},{"text":"was","start":41.028},{"text":"6","start":41.217},{"text":"km","start":41.406},{"text":"long.","start":41.595},{"text":"Its","start":41.784},{"text":"thunder","start":41.973},{"text":"used","start":42.162},{"text":"to","start":42.351},{"text":"roll","start":42.54},{"text":"on","start":42.729},{"text":"for","start":42.918},{"text":"13","start":43.107},{"text":"seconds,","start":43.296},{"text":"its","start":43.485},{"text":"far","start":43.674},{"text":"end","start":43.863},{"text":"heard","start":44.052},{"text":"last.","start":44.241}]},{"text":"Now all of it lands at once.","show":47.65,"hide":50.05,"words":[{"text":"Now","start":47.65},{"text":"all","start":47.89},{"text":"of","start":48.13},{"text":"it","start":48.37},{"text":"lands","start":48.61},{"text":"at","start":48.85},{"text":"once.","start":49.09}]}]},{"id":"call","n":6,"section":1,"title":false,"first":51.65,"end":61.8,"caps":[{"text":"Maisie isn't back. You call her name. The barn should throw it back to you.","show":51.65,"hide":56.4,"words":[{"text":"Maisie","start":51.65},{"text":"isn't","start":51.872},{"text":"back.","start":52.093},{"text":"You","start":52.315},{"text":"call","start":52.537},{"text":"her","start":52.758},{"text":"name.","start":52.98},{"text":"The","start":53.202},{"text":"barn","start":53.423},{"text":"should","start":53.645},{"text":"throw","start":53.867},{"text":"it","start":54.088},{"text":"back","start":54.31},{"text":"to","start":54.532},{"text":"you.","start":54.753}]},{"text":"No echo. Every echo now arrives with your voice.","show":58.4,"hide":61.8,"words":[{"text":"No","start":58.4},{"text":"echo.","start":58.664},{"text":"Every","start":58.929},{"text":"echo","start":59.193},{"text":"now","start":59.458},{"text":"arrives","start":59.722},{"text":"with","start":59.987},{"text":"your","start":60.251},{"text":"voice.","start":60.516}]}]},{"id":"answer","n":7,"section":1,"title":false,"first":63.8,"end":71.15,"caps":[{"text":"She's calling back. You can hear her perfectly.","show":63.8,"hide":67.15,"words":[{"text":"She's","start":63.8},{"text":"calling","start":64.093},{"text":"back.","start":64.386},{"text":"You","start":64.679},{"text":"can","start":64.973},{"text":"hear","start":65.266},{"text":"her","start":65.559},{"text":"perfectly.","start":65.852}]},{"text":"You can't tell where she is.","show":68.75,"hide":71.15,"words":[{"text":"You","start":68.75},{"text":"can't","start":69.03},{"text":"tell","start":69.31},{"text":"where","start":69.59},{"text":"she","start":69.87},{"text":"is.","start":70.15}]}]},{"id":"ears","n":8,"section":1,"title":false,"first":72.35,"end":89.7,"caps":[{"text":"Your brain finds a sound by the gap between your two ears: up to 0.66 thousandths of a second.","show":72.35,"hide":77.75,"words":[{"text":"Your","start":72.35},{"text":"brain","start":72.549},{"text":"finds","start":72.748},{"text":"a","start":72.947},{"text":"sound","start":73.146},{"text":"by","start":73.345},{"text":"the","start":73.544},{"text":"gap","start":73.743},{"text":"between","start":73.942},{"text":"your","start":74.141},{"text":"two","start":74.339},{"text":"ears:","start":74.538},{"text":"up","start":74.737},{"text":"to","start":74.936},{"text":"0.66","start":75.135},{"text":"thousandths","start":75.334},{"text":"of","start":75.533},{"text":"a","start":75.732},{"text":"second.","start":75.931}]},{"text":"Now it's 0.2 billionths: 44,000 times too short for your brain.","show":78.95,"hide":83.1,"words":[{"text":"Now","start":78.95},{"text":"it's","start":79.214},{"text":"0.2","start":79.478},{"text":"billionths:","start":79.742},{"text":"44,000","start":80.006},{"text":"times","start":80.27},{"text":"too","start":80.535},{"text":"short","start":80.799},{"text":"for","start":81.063},{"text":"your","start":81.327},{"text":"brain.","start":81.591}]},{"text":"Her voice's waves are now 3,300 km long. They flow round your head as if it weren't there.","show":84.3,"hide":89.7,"words":[{"text":"Her","start":84.3},{"text":"voice's","start":84.51},{"text":"waves","start":84.72},{"text":"are","start":84.93},{"text":"now","start":85.14},{"text":"3,300","start":85.35},{"text":"km","start":85.56},{"text":"long.","start":85.77},{"text":"They","start":85.98},{"text":"flow","start":86.19},{"text":"round","start":86.4},{"text":"your","start":86.61},{"text":"head","start":86.82},{"text":"as","start":87.03},{"text":"if","start":87.24},{"text":"it","start":87.45},{"text":"weren't","start":87.66},{"text":"there.","start":87.87}]}]},{"id":"head","n":9,"section":1,"title":false,"first":91.3,"end":104.3,"caps":[{"text":"Every sound now seems to come from inside your head.","show":91.3,"hide":94.9,"words":[{"text":"Every","start":91.3},{"text":"sound","start":91.552},{"text":"now","start":91.804},{"text":"seems","start":92.056},{"text":"to","start":92.308},{"text":"come","start":92.56},{"text":"from","start":92.812},{"text":"inside","start":93.064},{"text":"your","start":93.316},{"text":"head.","start":93.568}]},{"text":"Louder means closer. That's all you have left.","show":96.3,"hide":99.6,"words":[{"text":"Louder","start":96.3},{"text":"means","start":96.589},{"text":"closer.","start":96.878},{"text":"That's","start":97.166},{"text":"all","start":97.455},{"text":"you","start":97.744},{"text":"have","start":98.033},{"text":"left.","start":98.321}]},{"text":"You walk along the corn. She gets quieter.","show":101.2,"hide":104.3,"words":[{"text":"You","start":101.2},{"text":"walk","start":101.471},{"text":"along","start":101.743},{"text":"the","start":102.014},{"text":"corn.","start":102.285},{"text":"She","start":102.556},{"text":"gets","start":102.828},{"text":"quieter.","start":103.099}]}]},{"id":"far","n":10,"section":1,"title":false,"first":105.9,"end":121.5,"caps":[{"text":"A freight train blows its horn 11 km away.","show":105.9,"hide":109,"words":[{"text":"A","start":105.9},{"text":"freight","start":106.141},{"text":"train","start":106.382},{"text":"blows","start":106.623},{"text":"its","start":106.864},{"text":"horn","start":107.106},{"text":"11","start":107.347},{"text":"km","start":107.588},{"text":"away.","start":107.829}]},{"text":"You hear it at the same instant as the Hansens' dogs, 1.4 km away.","show":110.4,"hide":114.7,"words":[{"text":"You","start":110.4},{"text":"hear","start":110.615},{"text":"it","start":110.83},{"text":"at","start":111.045},{"text":"the","start":111.26},{"text":"same","start":111.475},{"text":"instant","start":111.69},{"text":"as","start":111.905},{"text":"the","start":112.12},{"text":"Hansens'","start":112.335},{"text":"dogs,","start":112.55},{"text":"1.4","start":112.765},{"text":"km","start":112.98},{"text":"away.","start":113.195}]},{"text":"Everything for kilometres around, all at once, inside your head. Somewhere in it is her voice.","show":116.1,"hide":121.5,"words":[{"text":"Everything","start":116.1},{"text":"for","start":116.336},{"text":"kilometres","start":116.572},{"text":"around,","start":116.809},{"text":"all","start":117.045},{"text":"at","start":117.281},{"text":"once,","start":117.518},{"text":"inside","start":117.754},{"text":"your","start":117.99},{"text":"head.","start":118.226},{"text":"Somewhere","start":118.462},{"text":"in","start":118.699},{"text":"it","start":118.935},{"text":"is","start":119.171},{"text":"her","start":119.408},{"text":"voice.","start":119.644}]}]},{"id":"siren","n":11,"section":2,"title":false,"first":123.7,"end":139.5,"caps":[{"text":"The tornado sirens in town, 6 km away. You can't tell which way the town is.","show":123.7,"hide":128.5,"words":[{"text":"The","start":123.7},{"text":"tornado","start":123.91},{"text":"sirens","start":124.12},{"text":"in","start":124.33},{"text":"town,","start":124.54},{"text":"6","start":124.75},{"text":"km","start":124.96},{"text":"away.","start":125.17},{"text":"You","start":125.38},{"text":"can't","start":125.59},{"text":"tell","start":125.8},{"text":"which","start":126.01},{"text":"way","start":126.22},{"text":"the","start":126.43},{"text":"town","start":126.64},{"text":"is.","start":126.85}]},{"text":"A sheriff's car. Its siren should drop in pitch as it passes. It doesn't.","show":130.5,"hide":135.15,"words":[{"text":"A","start":130.5},{"text":"sheriff's","start":130.732},{"text":"car.","start":130.965},{"text":"Its","start":131.198},{"text":"siren","start":131.43},{"text":"should","start":131.663},{"text":"drop","start":131.895},{"text":"in","start":132.128},{"text":"pitch","start":132.36},{"text":"as","start":132.593},{"text":"it","start":132.825},{"text":"passes.","start":133.058},{"text":"It","start":133.29},{"text":"doesn't.","start":133.523}]},{"text":"You can't tell if it's coming or going.","show":136.55,"hide":139.5,"words":[{"text":"You","start":136.55},{"text":"can't","start":136.808},{"text":"tell","start":137.066},{"text":"if","start":137.324},{"text":"it's","start":137.583},{"text":"coming","start":137.841},{"text":"or","start":138.099},{"text":"going.","start":138.357}]}]},{"id":"tornado","n":12,"section":2,"title":false,"first":142.1,"end":154.55,"caps":[{"text":"In the flash: a tornado, 3 km west.","show":142.1,"hide":144.85,"words":[{"text":"In","start":142.1},{"text":"the","start":142.341},{"text":"flash:","start":142.581},{"text":"a","start":142.822},{"text":"tornado,","start":143.063},{"text":"3","start":143.303},{"text":"km","start":143.544},{"text":"west.","start":143.784}]},{"text":"Its roar is already here. It sounds as close as the rain.","show":146.05,"hide":149.9,"words":[{"text":"Its","start":146.05},{"text":"roar","start":146.275},{"text":"is","start":146.499},{"text":"already","start":146.724},{"text":"here.","start":146.948},{"text":"It","start":147.173},{"text":"sounds","start":147.398},{"text":"as","start":147.622},{"text":"close","start":147.847},{"text":"as","start":148.071},{"text":"the","start":148.296},{"text":"rain.","start":148.52}]},{"text":"It's getting louder. That's all you know.","show":151.5,"hide":154.55,"words":[{"text":"It's","start":151.5},{"text":"getting","start":151.805},{"text":"louder.","start":152.11},{"text":"That's","start":152.415},{"text":"all","start":152.72},{"text":"you","start":153.025},{"text":"know.","start":153.33}]}]},{"id":"phone","n":13,"section":3,"title":false,"first":156.15,"end":175.45,"caps":[{"text":"You call her phone again. It rings as if it were in your own pocket.","show":156.15,"hide":160.55,"words":[{"text":"You","start":156.15},{"text":"call","start":156.355},{"text":"her","start":156.561},{"text":"phone","start":156.766},{"text":"again.","start":156.971},{"text":"It","start":157.177},{"text":"rings","start":157.382},{"text":"as","start":157.587},{"text":"if","start":157.793},{"text":"it","start":157.998},{"text":"were","start":158.203},{"text":"in","start":158.409},{"text":"your","start":158.614},{"text":"own","start":158.819},{"text":"pocket.","start":159.025}]},{"text":"This time she answers. You hear her twice: through the air, then on the phone.","show":162.35,"hide":167.25,"words":[{"text":"This","start":162.35},{"text":"time","start":162.579},{"text":"she","start":162.807},{"text":"answers.","start":163.036},{"text":"You","start":163.265},{"text":"hear","start":163.493},{"text":"her","start":163.722},{"text":"twice:","start":163.951},{"text":"through","start":164.179},{"text":"the","start":164.408},{"text":"air,","start":164.637},{"text":"then","start":164.865},{"text":"on","start":165.094},{"text":"the","start":165.323},{"text":"phone.","start":165.551}]},{"text":"Her phone says she's 120 metres into the corn.","show":168.65,"hide":171.95,"words":[{"text":"Her","start":168.65},{"text":"phone","start":168.907},{"text":"says","start":169.163},{"text":"she's","start":169.42},{"text":"120","start":169.677},{"text":"metres","start":169.933},{"text":"into","start":170.19},{"text":"the","start":170.447},{"text":"corn.","start":170.703}]},{"text":"West. Towards the tornado.","show":173.15,"hide":175.45,"words":[{"text":"West.","start":173.15},{"text":"Towards","start":173.553},{"text":"the","start":173.955},{"text":"tornado.","start":174.358}]}]},{"id":"corn","n":14,"section":3,"title":false,"first":177.25,"end":193.85,"caps":[{"text":"You run into the corn. It's 2.4 metres tall. Your torch shows you one row at a time.","show":177.25,"hide":182.45,"words":[{"text":"You","start":177.25},{"text":"run","start":177.452},{"text":"into","start":177.654},{"text":"the","start":177.857},{"text":"corn.","start":178.059},{"text":"It's","start":178.261},{"text":"2.4","start":178.463},{"text":"metres","start":178.666},{"text":"tall.","start":178.868},{"text":"Your","start":179.07},{"text":"torch","start":179.272},{"text":"shows","start":179.474},{"text":"you","start":179.677},{"text":"one","start":179.879},{"text":"row","start":180.081},{"text":"at","start":180.283},{"text":"a","start":180.486},{"text":"time.","start":180.688}]},{"text":"Beyond it, you only see when the lightning strikes.","show":184.25,"hide":187.8,"words":[{"text":"Beyond","start":184.25},{"text":"it,","start":184.526},{"text":"you","start":184.802},{"text":"only","start":185.078},{"text":"see","start":185.354},{"text":"when","start":185.631},{"text":"the","start":185.907},{"text":"lightning","start":186.183},{"text":"strikes.","start":186.459}]},{"text":"She sounds like she's right beside you. She's 90 metres away.","show":189.8,"hide":193.85,"words":[{"text":"She","start":189.8},{"text":"sounds","start":190.058},{"text":"like","start":190.315},{"text":"she's","start":190.573},{"text":"right","start":190.831},{"text":"beside","start":191.089},{"text":"you.","start":191.346},{"text":"She's","start":191.604},{"text":"90","start":191.862},{"text":"metres","start":192.12},{"text":"away.","start":192.377}]}]},{"id":"strike","n":15,"section":3,"title":false,"first":195.65,"end":198.7,"caps":[{"text":"Lightning hits the yard light behind you.","show":195.65,"hide":198.7,"words":[{"text":"Lightning","start":195.65},{"text":"hits","start":195.955},{"text":"the","start":196.26},{"text":"yard","start":196.565},{"text":"light","start":196.87},{"text":"behind","start":197.175},{"text":"you.","start":197.48}]}]},{"id":"wind","n":16,"section":3,"title":false,"first":202.9,"end":211.6,"caps":[{"text":"The wind is rushing in towards the tornado at 90 km/h.","show":202.9,"hide":206.6,"words":[{"text":"The","start":202.9},{"text":"wind","start":203.135},{"text":"is","start":203.371},{"text":"rushing","start":203.606},{"text":"in","start":203.842},{"text":"towards","start":204.077},{"text":"the","start":204.313},{"text":"tornado","start":204.548},{"text":"at","start":204.784},{"text":"90","start":205.019},{"text":"km/h.","start":205.255}]},{"text":"The corn is lying down. All of it pointing west.","show":208.2,"hide":211.6,"words":[{"text":"The","start":208.2},{"text":"corn","start":208.438},{"text":"is","start":208.676},{"text":"lying","start":208.914},{"text":"down.","start":209.152},{"text":"All","start":209.39},{"text":"of","start":209.628},{"text":"it","start":209.866},{"text":"pointing","start":210.104},{"text":"west.","start":210.342}]}]},{"id":"neighbour","n":17,"section":3,"title":false,"first":215,"end":225.3,"caps":[{"text":"The Hansen farm, 1.3 km west. The tornado is on it.","show":215,"hide":218.55,"words":[{"text":"The","start":215},{"text":"Hansen","start":215.226},{"text":"farm,","start":215.452},{"text":"1.3","start":215.678},{"text":"km","start":215.904},{"text":"west.","start":216.13},{"text":"The","start":216.355},{"text":"tornado","start":216.581},{"text":"is","start":216.807},{"text":"on","start":217.033},{"text":"it.","start":217.259}]},{"text":"You hear its roof go. You can't tell if that was a kilometre away, or a hundred metres.","show":219.95,"hide":225.3,"words":[{"text":"You","start":219.95},{"text":"hear","start":220.158},{"text":"its","start":220.366},{"text":"roof","start":220.574},{"text":"go.","start":220.782},{"text":"You","start":220.99},{"text":"can't","start":221.198},{"text":"tell","start":221.406},{"text":"if","start":221.614},{"text":"that","start":221.823},{"text":"was","start":222.031},{"text":"a","start":222.239},{"text":"kilometre","start":222.447},{"text":"away,","start":222.655},{"text":"or","start":222.863},{"text":"a","start":223.071},{"text":"hundred","start":223.279},{"text":"metres.","start":223.487}]}]},{"id":"found","n":18,"section":3,"title":false,"first":226.6,"end":233.7,"caps":[{"text":"A flash. A yellow raincoat, 6 metres away.","show":226.6,"hide":229.7,"words":[{"text":"A","start":226.6},{"text":"flash.","start":226.871},{"text":"A","start":227.142},{"text":"yellow","start":227.414},{"text":"raincoat,","start":227.685},{"text":"6","start":227.956},{"text":"metres","start":228.228},{"text":"away.","start":228.499}]},{"text":"You have her. She's shaking.","show":231.3,"hide":233.7,"words":[{"text":"You","start":231.3},{"text":"have","start":231.636},{"text":"her.","start":231.972},{"text":"She's","start":232.308},{"text":"shaking.","start":232.644}]}]},{"id":"back","n":19,"section":3,"title":false,"first":235.3,"end":252.05,"caps":[{"text":"The storm cellar is 130 metres behind you. Carrying her, that's 54 seconds.","show":235.3,"hide":240.05,"words":[{"text":"The","start":235.3},{"text":"storm","start":235.556},{"text":"cellar","start":235.812},{"text":"is","start":236.067},{"text":"130","start":236.323},{"text":"metres","start":236.579},{"text":"behind","start":236.835},{"text":"you.","start":237.09},{"text":"Carrying","start":237.346},{"text":"her,","start":237.602},{"text":"that's","start":237.858},{"text":"54","start":238.113},{"text":"seconds.","start":238.369}]},{"text":"If the tornado is coming straight at you, its winds reach the cellar in 51.","show":241.65,"hide":246.4,"words":[{"text":"If","start":241.65},{"text":"the","start":241.872},{"text":"tornado","start":242.093},{"text":"is","start":242.315},{"text":"coming","start":242.537},{"text":"straight","start":242.758},{"text":"at","start":242.98},{"text":"you,","start":243.202},{"text":"its","start":243.423},{"text":"winds","start":243.645},{"text":"reach","start":243.867},{"text":"the","start":244.088},{"text":"cellar","start":244.31},{"text":"in","start":244.532},{"text":"51.","start":244.753}]},{"text":"You can hear it everywhere. You can't hear which way it's moving.","show":247.8,"hide":252.05,"words":[{"text":"You","start":247.8},{"text":"can","start":248.048},{"text":"hear","start":248.296},{"text":"it","start":248.544},{"text":"everywhere.","start":248.792},{"text":"You","start":249.04},{"text":"can't","start":249.288},{"text":"hear","start":249.535},{"text":"which","start":249.783},{"text":"way","start":250.031},{"text":"it's","start":250.279},{"text":"moving.","start":250.527}]}]},{"id":"question","n":20,"section":3,"title":false,"first":253.65,"end":257.45,"caps":[{"text":"Which way would you run?","show":253.65,"hide":257.45,"words":[{"text":"Which","start":253.65},{"text":"way","start":253.958},{"text":"would","start":254.266},{"text":"you","start":254.574},{"text":"run?","start":254.882}]}]}]};
